-- zz_tw_mc_scale_80.sql
-- Timewalking MC: ONLY bosses cloned to L83 (~T7+20%); trash keep original L62 templates.
-- new_entry = 9100000 + old_entry. Idempotent.
SET NAMES utf8mb4;

-- Cleanup previous TW clones (boss+trash from earlier full scale)
