-- Revert ALL map 960 combat spawns to original ids first
UPDATE `creature` SET `id`=`id`-9100000 WHERE `map`=960 AND `id`>=9100000 AND `id`<9100000+100000 AND `id` NOT IN (9000100,9000101);

