-- Boss models / locale / addon / equip / movement / resistance / spell
INSERT INTO `creature_template_model` (`CreatureID`,`Idx`,`CreatureDisplayID`,`DisplayScale`,`Probability`) SELECT `CreatureID`+9100000,`Idx`,`CreatureDisplayID`,`DisplayScale`,`Probability` FROM `creature_template_model` WHERE `CreatureID` IN (11982,11988,12056,12057,12098,12118,12259,12264);
INSERT INTO `creature_template_locale` (`entry`,`locale`,`Name`,`Title`,`VerifiedBuild`) SELECT `entry`+9100000,`locale`,CONCAT(`Name`,'（时光）'),`Title`,`VerifiedBuild` FROM `creature_template_locale` WHERE `entry` IN (11982,11988,12056,12057,12098,12118,12259,12264);
INSERT INTO `creature_template_addon` SELECT `entry`+9100000, `path_id`, `mount`, `bytes1`, `bytes2`, `emote`, `visibilityDistanceType`, `auras` FROM `creature_template_addon` WHERE `entry` IN (11982,11988,12056,12057,12098,12118,12259,12264);
INSERT INTO `creature_equip_template` (`CreatureID`,`ID`,`ItemID1`,`ItemID2`,`ItemID3`,`VerifiedBuild`) SELECT `CreatureID`+9100000, `ID`, `ItemID1`, `ItemID2`, `ItemID3`, `VerifiedBuild` FROM `creature_equip_template` WHERE `CreatureID` IN (11982,11988,12056,12057,12098,12118,12259,12264);
INSERT INTO `creature_template_movement` (`CreatureId`,`Ground`,`Swim`,`Flight`,`Rooted`,`Chase`,`Random`,`InteractionPauseTimer`) SELECT `CreatureId`+9100000, `Ground`, `Swim`, `Flight`, `Rooted`, `Chase`, `Random`, `InteractionPauseTimer` FROM `creature_template_movement` WHERE `CreatureId` IN (11982,11988,12056,12057,12098,12118,12259,12264);
INSERT INTO `creature_template_resistance` (`CreatureID`,`School`,`Resistance`,`VerifiedBuild`) SELECT `CreatureID`+9100000, `School`, `Resistance`, `VerifiedBuild` FROM `creature_template_resistance` WHERE `CreatureID` IN (11982,11988,12056,12057,12098,12118,12259,12264);
INSERT INTO `creature_template_spell` (`CreatureID`,`Index`,`Spell`,`VerifiedBuild`) SELECT `CreatureID`+9100000, `Index`, `Spell`, `VerifiedBuild` FROM `creature_template_spell` WHERE `CreatureID` IN (11982,11988,12056,12057,12098,12118,12259,12264);

